/**
 * Self-signed TLS certificate for the WSS listener of Asterisk.
 *
 * node-forge is used instead of `@peculiar/x509`: it is synchronous, CommonJS like this adapter, has no
 * WebCrypto dependency and is already used throughout the ioBroker ecosystem. The RSA key itself is
 * generated by node's crypto (native, fast) and only handed to forge to build and sign the certificate.
 * The fingerprint comes from node's own X509Certificate, which formats it exactly like
 * `openssl x509 -noout -fingerprint -sha256`.
 */
import { generateKeyPairSync, randomBytes, X509Certificate } from 'node:crypto';
import { isIP } from 'node:net';
import { hostname, networkInterfaces } from 'node:os';
import forge from 'node-forge';

export const CERT_COMMON_NAME = 'ioBroker WebRTC PBX';
export const CERT_VALIDITY_YEARS = 10;

export interface GeneratedCertificate {
    certPublic: string;
    certPrivate: string;
    certFingerprint: string;
}

/** SHA-256 fingerprint over the DER of the first certificate in the PEM, `AB:CD:…` */
export function getFingerprint(pem: string): string {
    return new X509Certificate(pem).fingerprint256.toUpperCase();
}

/** All IP and DNS entries of the subjectAltName of the first certificate in the PEM */
export function getSubjectAltNames(pem: string): string[] {
    const san = new X509Certificate(pem).subjectAltName;
    if (!san) {
        return [];
    }
    return san
        .split(',')
        .map(entry => entry.trim())
        .map(entry => entry.replace(/^(DNS|IP Address):/, ''))
        .filter(Boolean);
}

/** Non-internal IPv4 addresses and the host name of this host - proposal for the SAN */
export function getHostAddresses(): string[] {
    const result: string[] = [];
    const interfaces = networkInterfaces();
    for (const name of Object.keys(interfaces)) {
        for (const address of interfaces[name] || []) {
            if (address.family === 'IPv4' && !address.internal && !result.includes(address.address)) {
                result.push(address.address);
            }
        }
    }
    const host = hostname();
    if (host && !result.includes(host)) {
        result.push(host);
    }
    return result;
}

/**
 * Create a self-signed certificate: RSA 2048, SHA-256, valid for 10 years, with all given hosts in the SAN.
 *
 * @param hosts IP addresses and host names for the subjectAltName
 */
export function generateCertificate(hosts: string[]): GeneratedCertificate {
    const cleanHosts = [...new Set((hosts || []).map(h => (h || '').trim()).filter(Boolean))];
    if (!cleanHosts.length) {
        throw new Error('At least one host or IP address is required for the certificate');
    }

    const { privateKey, publicKey } = generateKeyPairSync('rsa', {
        modulusLength: 2048,
        publicKeyEncoding: { type: 'spki', format: 'pem' },
        privateKeyEncoding: { type: 'pkcs8', format: 'pem' },
    });

    const cert = forge.pki.createCertificate();
    cert.publicKey = forge.pki.publicKeyFromPem(publicKey);
    // Positive serial number: the highest bit of the first byte must be cleared
    const serial = randomBytes(16);
    serial[0] &= 0x7f;
    cert.serialNumber = serial.toString('hex');

    const notBefore = new Date();
    // Tolerate clocks of clients that are a little behind
    notBefore.setMinutes(notBefore.getMinutes() - 5);
    const notAfter = new Date(notBefore);
    notAfter.setFullYear(notAfter.getFullYear() + CERT_VALIDITY_YEARS);
    cert.validity.notBefore = notBefore;
    cert.validity.notAfter = notAfter;

    const attrs = [{ name: 'commonName', value: CERT_COMMON_NAME }];
    cert.setSubject(attrs);
    cert.setIssuer(attrs);
    cert.setExtensions([
        { name: 'basicConstraints', cA: false, critical: true },
        { name: 'keyUsage', digitalSignature: true, keyEncipherment: true, critical: true },
        { name: 'extKeyUsage', serverAuth: true },
        {
            name: 'subjectAltName',
            // type 7 = IP address, type 2 = DNS name
            altNames: cleanHosts.map(host => (isIP(host) ? { type: 7, ip: host } : { type: 2, value: host })),
        },
        { name: 'subjectKeyIdentifier' },
    ]);
    cert.sign(forge.pki.privateKeyFromPem(privateKey), forge.md.sha256.create());

    const certPublic = forge.pki.certificateToPem(cert);
    // Asterisk (OpenSSL) reads PKCS#1 and PKCS#8 alike; PKCS#1 is the most compatible form
    const certPrivate = forge.pki.privateKeyToPem(forge.pki.privateKeyFromPem(privateKey));

    return { certPublic, certPrivate, certFingerprint: getFingerprint(certPublic) };
}

/** Hosts of this machine that are not covered by the SAN of the certificate */
export function getUncoveredHosts(pem: string, hosts: string[]): string[] {
    let san: string[];
    try {
        san = getSubjectAltNames(pem).map(h => h.toLowerCase());
    } catch {
        return hosts;
    }
    return hosts.filter(h => !san.includes(h.toLowerCase()));
}
